package usernamepolicy

import (
	_ "embed"
	"sync"
)

// Official lexicon, byte-for-byte policy/dist/policy-2026092301.json
// from tellomi/tellomi. Do not edit this file.
//
//go:embed policy/policy-2026092301.json
var officialPolicy []byte

// D-56 names that the official file does not already reserve.
//
//go:embed policy/overlay-d56.json
var overlayPolicy []byte

var (
	officialOnce sync.Once
	officialEng  *Engine
	officialErr  error

	runtimeOnce sync.Once
	runtimeEng  *Engine
	runtimeErr  error
)

func officialEngine() *Engine {
	officialOnce.Do(func() {
		officialEng, officialErr = Load(officialPolicy)
	})
	if officialErr != nil {
		panic(officialErr)
	}
	return officialEng
}

func runtimeEngine() *Engine {
	runtimeOnce.Do(func() {
		base, err := Load(officialPolicy)
		if err != nil {
			runtimeErr = err
			return
		}
		extra, err := Load(overlayPolicy)
		if err != nil {
			runtimeErr = err
			return
		}
		rules := append(append([]rule{}, base.rules...), extra.rules...)
		allow := append([]allowEntry{}, base.allow...)
		if err := validate(rules); err != nil {
			runtimeErr = err
			return
		}
		runtimeEng = index(base.version, rules, allow)
	})
	if runtimeErr != nil {
		panic(runtimeErr)
	}
	return runtimeEng
}

func embeddedEngine() *Engine { return runtimeEngine() }
